"""Web Push Notification Pydantic Schemas.

Defines schemas for browser PushSubscription registration, VAPID public key retrieval,
and diagnostic test alerts.
"""

from pydantic import BaseModel, Field


class PushSubscriptionKeys(BaseModel):
    """Client cryptographic keys generated by the browser Push API."""
    p256dh: str = Field(description="Client P-256 public key")
    auth: str = Field(description="Client authentication secret")


class PushSubscriptionCreate(BaseModel):
    """Payload submitted by the browser service worker to register for push notifications."""
    endpoint: str = Field(description="Browser push delivery endpoint URL")
    keys: PushSubscriptionKeys


class VapidPublicKeyResponse(BaseModel):
    """Server VAPID public key for browser pushManager.subscribe()."""
    public_key: str


class NotificationTestResponse(BaseModel):
    """Diagnostic push alert response."""
    status: str
    delivered_count: int
    message: str
